// Persona contract shared with fastapi_app/persona.py. Keep both in sync.
const persona = [
  'تو «رادار سایبری» هستی: ترکیبی از یک رفیق صمیمیِ پرانرژی و یک هکر کلاه‌سفیدِ تاریک و پارانویید.',
  '',
  'قوانین سختگیرانه:',
  '1. فقط و فقط فارسی بنویس (نام ابزار/CVE به انگلیسی مجاز است).',
  '2. لحن: صمیمی، پرانرژی، کمی تاریک و بدبین نسبت به قدرت‌ها و شرکت‌ها.',
  '3. از اصطلاح «پشمام» به‌صورت طبیعی و به‌جا استفاده کن (زوری و تکراری نه).',
  '4. کلمات ممنوعه: هرگز و تحت هیچ شرایطی از «حاجی» یا «داداش» استفاده نکن.',
  '5. از ایموجی زیاد استفاده کن (🔥 😎 💣 🕶️ ⚡).',
  '6. خروجی را با HTML سبک تلگرام بنویس (<b>, <i>, <code>, <a href>)، نه Markdown.'
].join('\n');

const structure = [
  'ساختار خروجی:',
  '<b>[تیتر کوتاه و جذاب]</b> 🔥',
  'دو تا سه خط توضیح خودمانی از ماجرا.',
  '<b>⚙️ چرا مهمه؟</b> یک تا دو خط فنی.',
  '<b>🕶️ نگاه پارانوید:</b> یک خط بدبینانه.',
  'بدون مقدمه‌چینی و بدون تکرار لینک.'
].join('\n');

const item = $json;
const userPrompt = `خبر خام:\nعنوان: ${item.title}\nمنبع: ${item.source}\nدسته: ${item.category}\nخلاصه: ${item.summary || '—'}\nلینک: ${item.url}`;

return [{ json: { ...item, persona, system_prompt: persona + '\n\n' + structure, user_prompt: userPrompt } }];

const base = $('Build persona prompt').item.json;
const llm = $('HF · Editor agent').item.json;
const butterfly = $('Dystopian Butterfly Effect').item.json || {};
const collide = $json || {};

const banned = ['حاجی', 'داداش'];
let body = llm?.choices?.[0]?.message?.content || '';
if (!body.trim()) {
  body = `<b>${base.title}</b> 🔥\n${(base.summary || '').slice(0, 500)}`;
}
for (const word of banned) body = body.split(word).join('رفیق');

const parts = [body.trim()];
if (collide.collision && collide.text) parts.push(collide.text.trim());
if (butterfly.text) parts.push(butterfly.text.trim());
parts.push(`🔗 <a href="${base.url}">منبع</a>`);

return [{ json: { url: base.url, category: base.category, article: parts.join('\n\n') } }];
